/*
 * test_avian_scale.c — tests for the avian_scale kernels.
 *
 * Plain asserts, no framework. Exit 0 only when every check passes.
 *
 * The CBQN-vs-C comparison reads the fixture files generated by
 * cbqn/scale.bqn (fixtures/arrays/scale_<name>.txt). The fixture
 * format is one value per line: scale, count, input[count],
 * expected[count]. CBQN writes negative numbers with the high-minus
 * character U+00AF (UTF-8 bytes 0xC2 0xAF); read_number() normalizes
 * that byte sequence to ASCII '-' before parsing. This is a
 * formatting artifact only; the values are unchanged.
 *
 * Usage: ./test_avian_scale [fixture-dir]
 *   fixture-dir defaults to ../../fixtures/arrays (relative to src/c11).
 */

#include "avian_array.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int g_pass = 0;
static int g_fail = 0;

#define CHECK(cond) do { \
    if (cond) { g_pass++; } \
    else { g_fail++; fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); } \
} while (0)

/* Replace the UTF-8 high-minus (0xC2 0xAF) with ASCII '-' in place. */
static void normalize_minus(char *s)
{
    size_t i, j;
    for (i = 0, j = 0; s[i] != '\0'; i++) {
        if ((unsigned char)s[i] == 0xC2 && (unsigned char)s[i + 1] == 0xAF) {
            s[j++] = '-';
            i++;
        } else {
            s[j++] = s[i];
        }
    }
    s[j] = '\0';
}

static int read_line(FILE *f, char *buf, size_t n)
{
    if (fgets(buf, (int)n, f) == NULL) {
        return 0;
    }
    normalize_minus(buf);
    return 1;
}

/* Read one fixture file. Returns 1 on success. The caller frees
 * *input_out and *expected_out. */
static int read_fixture_f32(const char *path, float *scale_out,
                            float **input_out, float **expected_out,
                            size_t *count_out)
{
    FILE *f = fopen(path, "r");
    char buf[128];
    size_t i, n;
    float *in = NULL, *exp = NULL;
    float sc;

    if (f == NULL) {
        fprintf(stderr, "cannot open fixture %s\n", path);
        return 0;
    }
    if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
    sc = strtof(buf, NULL);
    if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
    n = (size_t)strtoul(buf, NULL, 10);
    in = (float *)malloc(n * sizeof(float));
    exp = (float *)malloc(n * sizeof(float));
    if (in == NULL || exp == NULL) { fclose(f); return 0; }
    for (i = 0; i < n; i++) {
        if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
        in[i] = strtof(buf, NULL);
    }
    for (i = 0; i < n; i++) {
        if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
        exp[i] = strtof(buf, NULL);
    }
    fclose(f);
    *scale_out = sc;
    *input_out = in;
    *expected_out = exp;
    *count_out = n;
    return 1;
}

static int read_fixture_i32(const char *path, int32_t *scale_out,
                            int32_t **input_out, int32_t **expected_out,
                            size_t *count_out)
{
    FILE *f = fopen(path, "r");
    char buf[128];
    size_t i, n;
    int32_t *in = NULL, *exp = NULL;
    int32_t sc;

    if (f == NULL) {
        fprintf(stderr, "cannot open fixture %s\n", path);
        return 0;
    }
    if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
    sc = (int32_t)strtol(buf, NULL, 10);
    if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
    n = (size_t)strtoul(buf, NULL, 10);
    in = (int32_t *)malloc(n * sizeof(int32_t));
    exp = (int32_t *)malloc(n * sizeof(int32_t));
    if (in == NULL || exp == NULL) { fclose(f); return 0; }
    for (i = 0; i < n; i++) {
        if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
        in[i] = (int32_t)strtol(buf, NULL, 10);
    }
    for (i = 0; i < n; i++) {
        if (!read_line(f, buf, sizeof buf)) { fclose(f); return 0; }
        exp[i] = (int32_t)strtol(buf, NULL, 10);
    }
    fclose(f);
    *scale_out = sc;
    *input_out = in;
    *expected_out = exp;
    *count_out = n;
    return 1;
}

static void test_fixture_f32(const char *dir, const char *name)
{
    char path[512];
    float sc, *in = NULL, *exp = NULL, *out = NULL;
    size_t n, i;
    avian_status st;

    snprintf(path, sizeof path, "%s/%s", dir, name);
    if (!read_fixture_f32(path, &sc, &in, &exp, &n)) {
        g_fail++;
        fprintf(stderr, "FAIL: could not read fixture %s\n", path);
        return;
    }
    out = (float *)malloc(n * sizeof(float));
    if (out == NULL) { g_fail++; return; }
    st = avian_scale_f32((avian_f32_output){out, n},
                         (avian_f32_input){in, n}, sc);
    CHECK(st == AVIAN_OK);
    for (i = 0; i < n; i++) {
        /* The fixtures use products exactly representable in f32,
         * so the comparison is bit-exact. */
        CHECK(out[i] == exp[i]);
    }
    free(in);
    free(exp);
    free(out);
}

static void test_fixture_i32(const char *dir, const char *name)
{
    char path[512];
    int32_t sc, *in = NULL, *exp = NULL, *out = NULL;
    size_t n, i;
    avian_status st;

    snprintf(path, sizeof path, "%s/%s", dir, name);
    if (!read_fixture_i32(path, &sc, &in, &exp, &n)) {
        g_fail++;
        fprintf(stderr, "FAIL: could not read fixture %s\n", path);
        return;
    }
    out = (int32_t *)malloc(n * sizeof(int32_t));
    if (out == NULL) { g_fail++; return; }
    st = avian_scale_i32((avian_i32_output){out, n},
                         (avian_i32_input){in, n}, sc);
    CHECK(st == AVIAN_OK);
    for (i = 0; i < n; i++) {
        CHECK(out[i] == exp[i]);
    }
    free(in);
    free(exp);
    free(out);
}

static void test_empty_and_singleton(void)
{
    float out1 = 123.0f;
    int32_t iout1 = 123;
    avian_status st;

    /* Empty input: count 0, NULL data is fine, nothing is written. */
    st = avian_scale_f32((avian_f32_output){&out1, 1},
                         (avian_f32_input){NULL, 0}, 2.5f);
    CHECK(st == AVIAN_OK);
    CHECK(out1 == 123.0f);
    st = avian_scale_i32((avian_i32_output){&iout1, 1},
                         (avian_i32_input){NULL, 0}, 3);
    CHECK(st == AVIAN_OK);
    CHECK(iout1 == 123);

    /* Singleton. */
    {
        float in = 4.0f, out = 0.0f;
        st = avian_scale_f32((avian_f32_output){&out, 1},
                             (avian_f32_input){&in, 1}, 2.5f);
        CHECK(st == AVIAN_OK);
        CHECK(out == 10.0f);
    }
    {
        int32_t in = -7, out = 0;
        st = avian_scale_i32((avian_i32_output){&out, 1},
                             (avian_i32_input){&in, 1}, 3);
        CHECK(st == AVIAN_OK);
        CHECK(out == -21);
    }
}

static void test_error_paths(void)
{
    float fin[4] = {1.0f, 2.0f, 3.0f, 4.0f};
    float fout[4] = {0};
    int32_t iin[4] = {1, 2, 3, 4};
    int32_t iout[4] = {0};
    float nan_in[2] = {1.0f, NAN};
    float inf_in[2] = {1.0f, INFINITY};
    float out2[2] = {9.0f, 9.0f};
    int32_t big[2] = {INT32_MAX, 2};
    int32_t iout2[2] = {9, 9};
    avian_status st;

    /* NULL data with count > 0. */
    st = avian_scale_f32((avian_f32_output){fout, 4},
                         (avian_f32_input){NULL, 4}, 2.0f);
    CHECK(st == AVIAN_ERR_NULL);
    st = avian_scale_f32((avian_f32_output){NULL, 4},
                         (avian_f32_input){fin, 4}, 2.0f);
    CHECK(st == AVIAN_ERR_NULL);
    st = avian_scale_i32((avian_i32_output){iout, 4},
                         (avian_i32_input){NULL, 4}, 2);
    CHECK(st == AVIAN_ERR_NULL);

    /* Output too small. */
    st = avian_scale_f32((avian_f32_output){fout, 2},
                         (avian_f32_input){fin, 4}, 2.0f);
    CHECK(st == AVIAN_ERR_COUNT);
    st = avian_scale_i32((avian_i32_output){iout, 2},
                         (avian_i32_input){iin, 4}, 2);
    CHECK(st == AVIAN_ERR_COUNT);

    /* Overlapping buffers: output starts inside the input.
     * output.count is set to input.count so the COUNT check passes
     * and the OVERLAP check is the one that fires. */
    st = avian_scale_f32((avian_f32_output){fin + 1, 4},
                         (avian_f32_input){fin, 4}, 2.0f);
    CHECK(st == AVIAN_ERR_OVERLAP);
    /* Identical buffers (complete overlap). */
    st = avian_scale_f32((avian_f32_output){fin, 4},
                         (avian_f32_input){fin, 4}, 2.0f);
    CHECK(st == AVIAN_ERR_OVERLAP);
    st = avian_scale_i32((avian_i32_output){iin + 2, 4},
                         (avian_i32_input){iin, 4}, 2);
    CHECK(st == AVIAN_ERR_OVERLAP);

    /* Non-finite input and scale (f32). The output must be untouched. */
    st = avian_scale_f32((avian_f32_output){out2, 2},
                         (avian_f32_input){nan_in, 2}, 2.0f);
    CHECK(st == AVIAN_ERR_NONFINITE);
    CHECK(out2[0] == 9.0f && out2[1] == 9.0f);
    st = avian_scale_f32((avian_f32_output){out2, 2},
                         (avian_f32_input){inf_in, 2}, 2.0f);
    CHECK(st == AVIAN_ERR_NONFINITE);
    CHECK(out2[0] == 9.0f && out2[1] == 9.0f);
    st = avian_scale_f32((avian_f32_output){out2, 2},
                         (avian_f32_input){fin, 2}, NAN);
    CHECK(st == AVIAN_ERR_NONFINITE);
    CHECK(out2[0] == 9.0f && out2[1] == 9.0f);
    st = avian_scale_f32((avian_f32_output){out2, 2},
                         (avian_f32_input){fin, 2}, INFINITY);
    CHECK(st == AVIAN_ERR_NONFINITE);
    CHECK(out2[0] == 9.0f && out2[1] == 9.0f);

    /* f32 product overflow to infinity is rejected, output untouched. */
    {
        float huge[1] = {3.0e38f};
        float o[1] = {9.0f};
        st = avian_scale_f32((avian_f32_output){o, 1},
                             (avian_f32_input){huge, 1}, 10.0f);
        CHECK(st == AVIAN_ERR_NONFINITE);
        CHECK(o[0] == 9.0f);
    }

    /* i32 overflow: the product does not fit, output untouched. */
    st = avian_scale_i32((avian_i32_output){iout2, 2},
                         (avian_i32_input){big, 2}, 2);
    CHECK(st == AVIAN_ERR_OVERFLOW);
    CHECK(iout2[0] == 9 && iout2[1] == 9);
    {
        int32_t neg[1] = {INT32_MIN};
        int32_t o[1] = {9};
        st = avian_scale_i32((avian_i32_output){o, 1},
                             (avian_i32_input){neg, 1}, -1);
        CHECK(st == AVIAN_ERR_OVERFLOW);
        CHECK(o[0] == 9);
    }
    /* INT32_MAX * 1 fits exactly. */
    {
        int32_t mx[1] = {INT32_MAX};
        int32_t o[1] = {0};
        st = avian_scale_i32((avian_i32_output){o, 1},
                             (avian_i32_input){mx, 1}, 1);
        CHECK(st == AVIAN_OK);
        CHECK(o[0] == INT32_MAX);
    }
}

static void test_signed_zero(void)
{
    float pz = 0.0f, nz = -0.0f, o1 = 1.0f, o2 = 1.0f;
    avian_status st;

    st = avian_scale_f32((avian_f32_output){&o1, 1},
                         (avian_f32_input){&pz, 1}, 2.5f);
    CHECK(st == AVIAN_OK);
    CHECK(o1 == 0.0f && signbit(o1) == 0);
    st = avian_scale_f32((avian_f32_output){&o2, 1},
                         (avian_f32_input){&nz, 1}, 2.5f);
    CHECK(st == AVIAN_OK);
    CHECK(o2 == 0.0f && signbit(o2) != 0);
}

int main(int argc, char **argv)
{
    const char *dir = (argc > 1) ? argv[1] : "../../fixtures/arrays";

    printf("avian_scale tests\n");
    printf("fixture dir: %s\n", dir);

    test_empty_and_singleton();
    test_error_paths();
    test_signed_zero();
    test_fixture_f32(dir, "scale_f32.txt");
    test_fixture_i32(dir, "scale_i32.txt");
    test_fixture_f32(dir, "scale_f32_large.txt");

    printf("checks passed: %d\n", g_pass);
    printf("checks failed: %d\n", g_fail);
    if (g_fail == 0) {
        printf("ALL TESTS PASSED\n");
        return 0;
    }
    printf("TESTS FAILED\n");
    return 1;
}
